<?php
$isStudent=$page==='students';$kind=$isStudent?'student':'invigilator';$table=$isStudent?'students':'invigilators';$edit=!empty($_GET['edit'])?owned($table,(int)$_GET['edit']):null;
$stages=[];foreach(rows('SELECT s.*,d.name AS department FROM stages s JOIN departments d ON d.id=s.department_id WHERE s.institution_id=? ORDER BY d.name,s.name',[inst()]) as $s)$stages[$s['id']]=$s['department'].' / '.$s['name'];
?>
<div class="heading"><div><div class="eyebrow"><?=$isStudent?'قوائم الامتحانات':'الفريق الامتحاني'?></div><h1><?=$isStudent?'إدارة الطلبة':'إدارة المراقبين'?></h1><p><?=$isStudent?'قوائم مستقلة لكل عام ودراسة وشعبة.':'التكليفات بالدقائق، مع مراعاة الاستثناءات والالتزامات.'?></p></div><?php if($isStudent):?><div class="actions"><a class="button secondary" href="?download=template">قالب Excel</a><a class="button secondary" href="?download=students">تصدير الطلبة Excel</a></div><?php endif;?></div>
<?php if(can('write')):?>
<section class="card"><h2><?=$edit?'تعديل البيانات':($isStudent?'إضافة طالب':'إضافة مراقب')?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="grid"><?php field('الاسم الكامل','name',$edit['name']??'');if($isStudent){field('الرمز / الرقم الجامعي','code',$edit['code']??'');selectf('القسم','department_id',opts('departments'),$edit['department_id']??'');selectf('المرحلة','stage_id',$stages,$edit['stage_id']??'');selectf('الدراسة','shift',['صباحي'=>'صباحي','مسائي'=>'مسائي'],$edit['shift']??'صباحي');field('الشعبة','section_name',$edit['section_name']??'','text','',false);}else{field('اللقب العلمي','academic_title',$edit['academic_title']??'');selectf('القسم','department_id',opts('departments'),$edit['department_id']??'',false);selectf('نوع التكليف','duty',['any'=>'رئاسة ومراقبة','chief'=>'مؤهل للرئاسة والمراقبة','observer'=>'مراقبة فقط'],$edit['duty']??'any');field('عبء سابق بالدقائق','baseline_minutes',$edit['baseline_minutes']??0,'number','min="0" max="1000000"');}?>
<label class="check"><input type="checkbox" name="active" value="1" <?=!$edit||$edit['active']?'checked':''?>>نشط</label><?php if($isStudent):?><label class="check"><input type="checkbox" name="needs_access" value="1" <?=!empty($edit['needs_access'])?'checked':''?>>يحتاج مقعد وصول ملائم</label><?php endif;?></div><button>حفظ البيانات</button><?php if($edit):?> <a href="?page=<?=$page?>">إلغاء التعديل</a><?php endif;?></form></section>
<?php if($isStudent):?><section class="card"><h2>استيراد دفعة طلبة من Excel أو CSV</h2><form method="post" enctype="multipart/form-data" class="toolbar"><?=csrf()?><input type="hidden" name="action" value="import-students"><label>ملف الاستيراد<input type="file" name="students_file" accept=".xlsx,.csv" required></label><button>فحص واستيراد الملف</button></form><p class="muted">الورقة الأولى، حتى 5000 طالب. الأعمدة: code,name,department,stage,shift,section,needs_access. اكتب الدراسة صباحي أو مسائي، والوصول 0 أو 1. الأقسام والمراحل تُعرّف مسبقًا. يُرفض الملف كله عند صف مكرر أو غير صحيح.</p></section><?php endif;endif;?>
<section class="card"><form method="get" class="toolbar"><input type="hidden" name="page" value="<?=$page?>"><?php field('بحث بالاسم'.($isStudent?' أو الرمز':''),'q',$_GET['q']??'','search','',false);?><button>بحث</button></form><div class="table-wrap"><table><tr><th>الاسم</th><?php if($isStudent):?><th>الرمز</th><th>القسم / المرحلة</th><th>الدراسة / الشعبة</th><th>الوصول</th><?php else:?><th>اللقب</th><th>التكليف</th><th>العبء السابق</th><?php endif;?><th>الحالة</th><th class="no-print">إجراء</th></tr>
<?php $q=trim($_GET['q']??'');$query="SELECT * FROM $table WHERE institution_id=?";$params=[inst()];if($isStudent){$query.=' AND year_id=?';$params[]=year_id();}if($q!==''){$query.=$isStudent?' AND (name LIKE ? OR code LIKE ?)':' AND name LIKE ?';$params[]='%'.$q.'%';if($isStudent)$params[]='%'.$q.'%';}$people=rows($query.' ORDER BY name',$params);foreach($people as $r):?><tr><td><?=h($r['name'])?></td><?php if($isStudent):?><td><?=h($r['code'])?></td><td><?=h(owned('departments',(int)$r['department_id'])['name'])?><small><?=h(owned('stages',(int)$r['stage_id'])['name'])?></small></td><td><?=h($r['shift'].' / '.$r['section_name'])?></td><td><?=$r['needs_access']?'مطلوب':'اعتيادي'?></td><?php else:?><td><?=h($r['academic_title'])?></td><td><?=h($r['duty']==='observer'?'مراقبة فقط':'مؤهل للرئاسة')?></td><td><?=(int)$r['baseline_minutes']?> دقيقة</td><?php endif;?><td><span class="badge <?=$r['active']?'':'draft'?>"><?=$r['active']?'نشط':'غير نشط'?></span></td><td class="no-print"><?php if(can('write')):?><a href="?page=<?=$page?>&edit=<?=(int)$r['id']?>">تعديل</a><form method="post" class="inline" data-confirm="إصدار رمز جديد يلغي الرمز السابق. هل تتابع؟"><?=csrf()?><input type="hidden" name="action" value="token"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="ghost">رمز البوابة</button></form><form method="post" class="inline" data-confirm="حذف السجل غير المرتبط فقط؟"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="<?=$table?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="ghost danger">حذف</button></form><?php endif;?></td></tr><?php endforeach;if(!$people):?><tr><td colspan="8" class="empty">لا توجد أسماء مطابقة.</td></tr><?php endif;?></table></div></section>
<?php if(!$isStudent):?><section class="card"><h2>استثناءات التفرغ والالتزامات الرسمية</h2><?php if(can('write')):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="availability"><div class="grid"><?php selectf('المراقب','invigilator_id',opts('invigilators'));field('من','starts_at','','datetime-local');field('إلى','ends_at','','datetime-local');field('السبب / الالتزام الرسمي','reason');?></div><button>إضافة الاستثناء</button></form><?php endif;?><div class="table-wrap"><table><tr><th>المراقب</th><th>من</th><th>إلى</th><th>السبب</th><th></th></tr><?php foreach(rows('SELECT a.*,i.name FROM invigilator_availability a JOIN invigilators i ON i.id=a.invigilator_id WHERE a.institution_id=? ORDER BY a.starts_at DESC',[inst()]) as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['starts_at'])?></td><td><?=h($r['ends_at'])?></td><td><?=h($r['reason'])?></td><td><?php if(can('write')):?><form method="post" class="inline"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="invigilator_availability"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="ghost danger">حذف</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
